import csv
from io import StringIO

def solve(x):
    data = {}
    if not x.strip():
        return data

    csv_file = StringIO(x)
    reader = csv.DictReader(csv_file)

    for row in reader:
        label = row['label']
        value = int(row['value'])

        if label not in data:
            data[label] = {'max': value, 'min': value}
        else:
            data[label]['max'] = max(data[label]['max'], value)
            data[label]['min'] = min(data[label]['min'], value)

    result = {label: data[label]['max'] - data[label]['min'] for label in data}
    return result
